def load() -> pd.DataFrame:
    with open('data/wildfire/input/nifc_human_caused_acres.csv', 'r') as f:
        lines = [f.readline() for _ in range(15)]
    return pd.DataFrame({'raw_line': lines})

def process(merged_data) -> pd.DataFrame:
    max_row = merged_data.loc[merged_data['cost_per_acre'].idxmax()]
    year = int(max_row['Year'])
    cost_per_acre = round(max_row['cost_per_acre'], 2)
    return pd.DataFrame({
        'Year': [year],
        'Cost_Per_Acre': [cost_per_acre]
    })
